<div class="field"><label>Task Name</label><input name="task_name" required value="{{ old('task_name',$task->task_name ?? '') }}" placeholder="e.g. Finish Laravel project"></div><div class="field"><label>Description</label><textarea name="description" rows="5" placeholder="Task details">{{ old('description',$task->description ?? '') }}</textarea></div><div class="row"><div class="field"><label>Status</label><select name="status"><option value="Pending" @selected(old('status',$task->status ?? 'Pending')==='Pending')>Pending</option><option value="Completed" @selected(old('status',$task->status ?? '')==='Completed')>Completed</option></select></div><div class="field"><label>Due Date</label><input type="date" name="due_date" required value="{{ old('due_date',isset($task)?$task->due_date->format('Y-m-d'):'') }}"></div></div>
